/* Maps a trigger type (low 16 bits) to its flag mask; unknown types give 0x210. */ s32 getTrackTriggerMask(s32 triggerType) {
    s32 typeLow16;

    typeLow16 = triggerType & 0xFFFF;
    switch (typeLow16) {
    default:
        return 0x210;
    case 2:
        return 0x200;
    case 1:
        return 0x10;
    case 4:
        return 0x22;
    case 5:
        return 0x32;
    case 8:
        return 0x800;
    case 16:
        return 0;
    case 32:
        return 0x08000000;
    }
}
